css:
.zig{display:grid;grid-template-columns:1fr 1fr;column-gap:80px;align-items:start}
.zig>*:nth-child(odd){padding-top:56px}
.zig>*:nth-child(even){padding-top:0}
/* 各カラムを独立フローに保つ。align-items:stretch や grid-auto-rows で揃えない */
.zig img{width:100%;height:auto;display:block}
@media(max-width:768px){.zig{grid-template-columns:1fr;row-gap:32px}.zig>*{padding-top:0}}
